import {createPaper} from './paper.js';
export function initReceiving({getData}){
 const $=s=>document.querySelector(s),dialog=$('#recipient-dialog'),canvas=$('#gift-canvas'),ctx=canvas.getContext('2d');
 const atlas=new Image();atlas.src='assets/gift-opening-30fps.webp';const ready=atlas.decode();ready.catch(()=>{});let frame=0,raf=0,revealTimer,playing=false,session=0,reader=null,reader3D=null,in3D=false,readerZoom=1;
 const threeMount=document.createElement('div');threeMount.id='reader-three';threeMount.className='reader-three';threeMount.hidden=true;$('#reader-view').append(threeMount);const threeButton=document.createElement('button');threeButton.className='reader-3d-button';threeButton.textContent='Ver em 3D · opcional';threeButton.setAttribute('aria-pressed','false');$('#reader-view').append(threeButton);
 const metrics={targetFps:30,totalFrames:90,renderedFrames:0,frameIndices:[],elapsedMs:0,state:'closed'};
 const draw=n=>{frame=n;const x=n%10,y=Math.floor(n/10);ctx.clearRect(0,0,600,600);ctx.drawImage(atlas,x*320,y*320,320,320,0,0,600,600);canvas.dataset.frame=String(n);};
 const skin=(el,data)=>{el.className='sprite '+data.theme.sheet+' row'+data.theme.row+' '+(el.id==='delivery-capi'?'delivery-capi':'received-capi');el.style.setProperty('--frame-x',(data.theme.col||0)*100/3+'%');};
 function fill(){const data=getData();$('#receiving-eyebrow').textContent=data.recipient?'Para '+data.recipient+'.':'Alguém lembrou de você.';$('#received-message').textContent=data.message||'Que bom ter você na minha história.';$('#revealed-title').textContent=data.recipient?'Um mimo para '+data.recipient+'.':'Feito para você.';skin($('#delivery-capi'),data);skin($('#received-capi'),data);const photo=$('#received-photo');photo.hidden=!data.photo;if(data.photo)photo.src=data.photo;else photo.removeAttribute('src');$('#received-capi').hidden=!!data.photo;const date=data.eventDate?new Date(data.eventDate+'T12:00:00').toLocaleDateString('pt-BR'):'';$('#received-event').hidden=data.format!=='convite';$('#received-event').textContent=[date,data.eventPlace].filter(Boolean).join(' · ');$('#receive-book').firstChild.textContent=data.format==='livro'?'Folhear meu mimo ':'Ver meu '+(data.format==='convite'?'convite ':'cartão ');}
 function reset(){session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);playing=false;in3D=false;readerZoom=1;threeMount.hidden=true;$('#reader-paper').hidden=false;threeButton.textContent='Ver em 3D · opcional';threeButton.setAttribute('aria-pressed','false');metrics.state='sealed';$('#receiving-sealed').hidden=false;$('#receiving-revealed').hidden=true;$('#reader-view').hidden=true;$('#unwrap-gift').disabled=true;$('#unwrap-gift').textContent='Preparando seu mimo…';$('#receiving-hint').textContent='A surpresa é sua. Abra no seu tempo.';canvas.setAttribute('aria-label','Presente fechado com um laço vermelho');ready.then(()=>{draw(0);$('#unwrap-gift').disabled=false;$('#unwrap-gift').textContent='Abrir meu presente';}).catch(()=>{$('#unwrap-gift').disabled=false;$('#unwrap-gift').textContent='Abrir a mensagem';});fill();}
 function reveal(){metrics.state='revealed';$('#receiving-sealed').hidden=true;$('#receiving-revealed').hidden=false;dialog.scrollTop=0;$('#receive-book').focus({preventScroll:true});}
 function play(){if(playing)return;playing=true;const ownSession=session;$('#unwrap-gift').disabled=true;$('#unwrap-gift').textContent='Um carinho se abrindo…';$('#receiving-hint').textContent='Preparado com você em cada detalhe.';metrics.frameIndices=[];metrics.renderedFrames=0;metrics.state='playing';
  if(getData().motionPaused||!atlas.complete||!atlas.naturalWidth){if(atlas.naturalWidth)draw(89);reveal();return;}
  let start;const tick=t=>{if(ownSession!==session)return;if(start===undefined)start=t;const index=Math.min(89,Math.floor((t-start)*30/1000));if(index!==frame||metrics.renderedFrames===0){draw(index);metrics.frameIndices.push(index);metrics.renderedFrames++;}metrics.elapsedMs=t-start;if(index<89){raf=requestAnimationFrame(tick);}else{canvas.setAttribute('aria-label','Presente aberto; uma carta com coração saiu da caixa');revealTimer=setTimeout(reveal,500);}};raf=requestAnimationFrame(tick);
 }
 const show=()=>{reset();dialog.showModal();document.body.style.overflow='hidden';};
 $('#recipient-preview').addEventListener('click',show);
 $('#unwrap-gift').addEventListener('click',play);$('#replay-gift').addEventListener('click',reset);
 const unlock=()=>{session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);document.body.style.overflow='';metrics.state='closed';};
 $('#recipient-close').addEventListener('click',()=>{dialog.close();unlock();});dialog.addEventListener('close',unlock);
 $('#receive-book').addEventListener('click',()=>{const view=$('#reader-view');view.hidden=!view.hidden;if(!view.hidden){if(!reader)reader=createPaper($('#reader-paper'),getData());else reader.set(getData());reader.open(true);reader.zoom(1);$('#reader-plus').focus({preventScroll:true});view.scrollIntoView({behavior:getData().motionPaused?'instant':'smooth',block:'nearest'});}});
 const zoomReader=value=>{readerZoom=Math.max(1,Math.min(2.2,value));reader?.zoom(readerZoom);reader3D?.zoom(readerZoom);};
 $('#reader-plus').addEventListener('click',()=>zoomReader(readerZoom+.2));$('#reader-minus').addEventListener('click',()=>zoomReader(readerZoom-.2));$('#reader-fit').addEventListener('click',()=>zoomReader(1));
 threeButton.addEventListener('click',async()=>{in3D=!in3D;zoomReader(1);$('#reader-paper').hidden=in3D;threeMount.hidden=!in3D;threeButton.setAttribute('aria-pressed',String(in3D));threeButton.textContent=in3D?'Voltar à leitura simples':'Ver em 3D · opcional';if(in3D){threeButton.disabled=true;try{if(!reader3D){const {createBook}=await import('./book.js');reader3D=await createBook(threeMount,getData());}reader3D.set(getData());reader3D.open(true);reader3D.motion(getData().motionPaused);reader3D.zoom(readerZoom);}catch{in3D=false;$('#reader-paper').hidden=false;threeMount.hidden=true;threeButton.textContent='Leitura simples disponível neste aparelho';threeButton.setAttribute('aria-pressed','false');}finally{threeButton.disabled=false;}}});
 $('#skip-opening').addEventListener('click',()=>{session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);reveal();});
 $('#larger-text').addEventListener('click',()=>{const large=dialog.classList.toggle('large-reading');$('#larger-text').setAttribute('aria-pressed',String(large));$('#larger-text').textContent=large?'Voltar ao tamanho normal':'Aumentar texto';});
 window.__giftAnimation=metrics;
 return {show};
}
